const niche = $('Execute Workflow Trigger').first().json.niche;
const timeseriesRaw = $('SerpAPI Timeseries').first().json;
const relatedRaw    = $('SerpAPI Related Queries').first().json;

// --- Timeseries ---
const timeline = (timeseriesRaw?.interest_over_time?.timeline_data || []).map(t => ({
  date:  t.date,
  value: t.values?.[0]?.extracted_value ?? 0
}));

// --- Trend direction: compare last 4 weeks vs previous 4 weeks ---
const recentSlice = timeline.slice(-4).map(t => t.value);
const prevSlice   = timeline.slice(-8, -4).map(t => t.value);
const avg = arr => arr.length ? arr.reduce((s, v) => s + v, 0) / arr.length : 0;
const recentAvg = avg(recentSlice);
const prevAvg   = avg(prevSlice);
const trendDirection = recentAvg > prevAvg * 1.1 ? 'rising'
                     : recentAvg < prevAvg * 0.9 ? 'falling'
                     : 'stable';

// --- Peak months for seasonality ---
const byMonth = {};
timeline.forEach(({ date, value }) => {
  const month = date?.split(' ')?.[0] || date?.slice(0, 7) || '';
  if (!byMonth[month]) byMonth[month] = [];
  byMonth[month].push(value);
});
const monthlyAvg = Object.entries(byMonth).map(([month, vals]) => ({
  month,
  avg: avg(vals)
})).sort((a, b) => b.avg - a.avg);
const peakMonths = monthlyAvg.slice(0, 3).map(m => m.month);
const lowMonths  = monthlyAvg.slice(-3).map(m => m.month);

// --- Related queries ---
const rising = (relatedRaw?.related_queries?.rising || []).map(r => ({
  query: r.query,
  value: r.extracted_value || r.value
}));
const top = (relatedRaw?.related_queries?.top || []).map(r => ({
  query: r.query,
  value: r.extracted_value || r.value
}));

const data = {
  timeline,
  trendDirection,
  peakMonths,
  lowMonths,
  risingQueries: rising.map(r => r.query),
  topQueries:    top.map(r => r.query),
  risingFull:    rising,
  topFull:       top
};

return [{ json: { source: 'google_trends', niche, data } }];
